* 1. DC Operating Point Analysis
op
let iss_op = i(Vsens1) + i(Vsens2)
let id1_op = i(Vsens1)
let id2_op = i(Vsens2)
print iss_op id1_op id2_op

* 2. DC Sweep on VI1 to find current steering limits
dc VI1 0.4 1.4 0.005
let id1 = i(Vsens1)
let id2 = i(Vsens2)
let iss_dc = id1 + id2
meas dc vi1_max when id2=1u fall=1
meas dc vi1_min when id1=1u rise=1

* 3. AC Analysis for small-signal gm
ac dec 10 1k 100k
let gm_meas = mag(i(Vsens1))
meas ac gm_val find gm_meas at=1k

* 4. Transient Analysis for AC current amplitude (Ex. 22.4)
tran 2u 2m
meas tran id1_max max i(Vsens1) from=1m to=2m
meas tran id1_min min i(Vsens1) from=1m to=2m
let id_ac_amp = (id1_max - id1_min) / 2
print id_ac_amp

quit
.endc
.end

